import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/index.md","filePath":"deployment/index.md","lastUpdated":1786911472000}`),a={name:`deployment/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /deployment.md for this page in Markdown format</div><h1 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to “Deployment”">​</a></h1><p>React Starter Kit deploys as three Cloudflare Workers backed by a Neon PostgreSQL database. Infrastructure is managed with Terraform.</p><h2 id="what-gets-deployed" tabindex="-1">What Gets Deployed <a class="header-anchor" href="#what-gets-deployed" aria-label="Permalink to “What Gets Deployed”">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Target</th><th>Description</th></tr></thead><tbody><tr><td><strong>Web Worker</strong></td><td>Cloudflare Workers</td><td>Edge router – receives all traffic, routes to app/api via service bindings</td></tr><tr><td><strong>App Worker</strong></td><td>Cloudflare Workers</td><td>Serves the React SPA and static assets</td></tr><tr><td><strong>API Worker</strong></td><td>Cloudflare Workers</td><td>Hono + tRPC server, authentication, database access</td></tr><tr><td><strong>Database</strong></td><td>Neon PostgreSQL</td><td>Managed Postgres with Hyperdrive connection pooling</td></tr><tr><td><strong>Infrastructure</strong></td><td>Terraform</td><td>Hyperdrive configurations, optional R2 storage</td></tr></tbody></table><p>See <a href="/architecture/">Architecture Overview</a> for how these components connect.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h2><ul><li><strong>Cloudflare account</strong> with Workers enabled</li><li><strong>Neon account</strong> for PostgreSQL hosting (<a href="https://get.neon.com/HD157BR" target="_blank" rel="noreferrer">sign up</a>)</li><li><strong>Terraform</strong> installed (<code>brew install terraform</code> or <a href="https://developer.hashicorp.com/terraform/install" target="_blank" rel="noreferrer">download</a>)</li><li><strong>Domain</strong> added to Cloudflare DNS (optional for initial setup)</li></ul><h2 id="environments" tabindex="-1">Environments <a class="header-anchor" href="#environments" aria-label="Permalink to “Environments”">​</a></h2><table tabindex="0"><thead><tr><th>Environment</th><th>Intended trigger</th><th>URL pattern</th><th>Purpose</th></tr></thead><tbody><tr><td>Development</td><td><code>bun dev</code></td><td><code>localhost:5173</code></td><td>Local development</td></tr><tr><td>Staging</td><td>Push to <code>main</code></td><td><code>staging.example.com</code></td><td>Pre-production validation</td></tr><tr><td>Production</td><td>Manual dispatch</td><td><code>example.com</code></td><td>Live environment</td></tr></tbody></table><p>Staging and production each have their own Wrangler configuration, Hyperdrive bindings, and Terraform workspace. Development is local and provisions no cloud resources. See <a href="/deployment/ci-cd">CI/CD</a> for deployment triggers. Automated deploys stay off until you set the <code>DEPLOY_ENABLED</code> repository variable, so a fresh clone runs CI only.</p><h2 id="deployment-checklist" tabindex="-1">Deployment Checklist <a class="header-anchor" href="#deployment-checklist" aria-label="Permalink to “Deployment Checklist”">​</a></h2><ol><li><strong>Provision infrastructure</strong> – run Terraform to create the Hyperdrive configurations. Workers, routes and the custom domain&#39;s DNS come from Wrangler at deploy time (<a href="/adr/002-terraform-wrangler-boundary">ADR-002</a>)</li><li><strong>Set secrets</strong> – configure <code>BETTER_AUTH_SECRET</code> and <code>RESEND_API_KEY</code>, plus secrets for any optional integrations you enable, via Wrangler. See <a href="/deployment/cloudflare">Cloudflare Workers</a> for the full list</li><li><strong>Build and verify</strong> – compile every workspace, prove each worker bundles, and confirm the Cloudflare identity and production account, all before anything changes</li><li><strong>Run migrations</strong> – apply the schema to your production database. See <a href="/deployment/production-database">Production Database</a></li><li><strong>Deploy the workers</strong> – <code>api</code>, then <code>app</code>, then <code>web</code>. Service bindings resolve by name at deploy time, and <code>web</code> holds the public route, so it flips last</li></ol><p>Steps 3 to 5 are what an automated release does; push to <code>main</code> or dispatch a production run and <a href="/deployment/ci-cd">CI/CD</a> handles them. To do it by hand:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Preflight – nothing here changes production</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/api/wrangler.jsonc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/app/wrangler.jsonc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/wrangler.jsonc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># \`--dry-run\` never authenticates, so confirm the account separately</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whoami</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --account</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">production-account-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Stop unless every command succeeded and <code>whoami</code> reports the account you meant. These are two blocks rather than one because an interactive shell does not stop on error – pasted together, a failed dry-run would scroll past and the migration would still run.</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Point of no return</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:migrate:production</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api:deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app:deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web:deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><p>The order matters for the same reason it does in CI: migrations run against workers that are still the old ones, so a schema change has to be <a href="/deployment/ci-cd#release-order">additive</a> until the new workers are live.</p><h2 id="section-pages" tabindex="-1">Section Pages <a class="header-anchor" href="#section-pages" aria-label="Permalink to “Section Pages”">​</a></h2><ul><li><a href="/deployment/cloudflare">Cloudflare Workers</a> – Wrangler config, secrets, build and deploy</li><li><a href="/deployment/production-database">Production Database</a> – Neon setup, Hyperdrive, running migrations</li><li><a href="/deployment/ci-cd">CI/CD</a> – GitHub Actions pipelines, verifying pull requests</li><li><a href="/deployment/monitoring">Monitoring</a> – Logs, analytics, rollbacks, troubleshooting</li></ul>`,20)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};